INSERT INTO "item" ("id","remote_id","source","list_type","title","description","url","mini_program_id","placeholder","icon_path","icon_name","recommend","vip_level","is_highlighted","is_online","is_ai","created_at","updated_at","published_at","document_id","comment_count") VALUES (80,1414,0,6,'Генерация заголовков статей','Создан, чтобы помочь контент-мейкерам быстро придумывать привлекательные заголовки статей. Благодаря интеллектуальному анализу ключевых слов и краткого содержания, приложение генерирует разнообразные, креативные предложения заголовков, которые выделят вашу статью среди множества других и легко привлекут внимание читателей.','','','','','',0,0,0,0,0,1786086030070,1786086030070,NULL,'j0ju8rc6yzinhhv25au6re7q',NULL);
