INSERT INTO "item" ("id","remote_id","source","list_type","title","description","url","mini_program_id","placeholder","icon_path","icon_name","recommend","vip_level","is_highlighted","is_online","is_ai","created_at","updated_at","published_at","document_id","comment_count") VALUES (85,1564,0,6,'Генератор пожеланий','Сделайте каждое пожелание уникальным. В этом быстро меняющемся мире мы понимаем, что вы хотите выразить свои чувства, но у вас мало времени. Наше программное обеспечение с помощью интеллектуальных алгоритмов, учитывая ваши потребности и эмоциональную окраску, создает для вас персонализированные пожелания.','','','','','',0,0,0,0,0,1786086030720,1786086030720,NULL,'hgzmhbzpk3dc48hz2q5xnse6',NULL);
